// Data layer for Settings → Organizations & repository access.
//
// Lists the installed accounts (GET /user/installations) enriched with role +
// plan. Memberships (GET /user/memberships/orgs) are read ONLY to label each
// installed org's role — NOT to surface "orgs you're not installed on": a
// GitHub-App user token can only see orgs where the app is installed, so that
// set is unknowable from the API (the "Install on more" footer + GitHub's own
// account picker is how users widen access instead).
//
// Plan/seat is PER-ORG (ADR 0020): the entitlement carries the SET of seated
// orgs, so we attribute each installed org its own state — `pro` (the viewer
// holds a live seat, carrying the seat + trial fields), `blocked` (an installed
// Organization with no seat — the gated state the Settings card explains), or
// `free` (a personal account, always free).

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  fetchUserInstallations,
  toAppInstallations,
  fetchOrgMemberships,
  toOrgMemberships,
  type AppInstallation,
} from '../../../github/client';
import {
  useEntitlement,
  useEntitlementLoading,
  seatForOrg,
} from '../../../billing/entitlement';
import { getCredential, type AuthMethod } from '../../../auth/tokenStore';
import type { Entitlement, OrgRole, SeatAssignment } from '../../../auth/oauthBroker';

export type AccountPlan =
  | { tier: 'free' }
  | { tier: 'pro'; seat: SeatAssignment }
  | { tier: 'blocked' } // installed org, no plan
  | { tier: 'seats-full' } // paid org, but no free seat for the viewer
  | { tier: 'loading' }
  | { tier: 'unknown' };

export interface InstalledAccount extends AppInstallation {
  /** 'owner' for the personal account; the GitHub org role otherwise. */
  role: OrgRole;
  plan: AccountPlan;
}

export interface OrgAccessData {
  /** 'pat' has no installation model — the section renders an explainer. */
  method: AuthMethod;
  /** First load (no data yet) — show skeletons. */
  isLoading: boolean;
  /** Background refetch while prior data stays on screen — show a subtle dot. */
  isRefreshing: boolean;
  isError: boolean;
  installed: InstalledAccount[];
  refetch: () => void;
}

/** Plan/seat for one account (ADR 0020): personal accounts are always free; an
 * org is `pro` when the viewer holds a seat in it, else `blocked` (installed but
 * unseated — the gated state the card explains). */
function planForAccount(
  acct: AppInstallation,
  ent: Entitlement | null,
  entLoading: boolean,
): AccountPlan {
  if (acct.account.type === 'User') return { tier: 'free' };
  // Entitlement still in first resolution → neutral "Checking plan…". NEVER
  // flash "No plan" before the answer is known (ADR 0020).
  if (entLoading) return { tier: 'loading' };
  // Settled but no entitlement (error / no cache) → no badge, still no flash.
  if (!ent) return { tier: 'unknown' };
  const seat = seatForOrg(ent, acct.account.id);
  if (seat) return { tier: 'pro', seat };
  // Paid org with no free seat for the viewer ≠ an unpaid org (ADR 0020).
  if ((ent.seatsFull ?? []).includes(acct.account.id)) return { tier: 'seats-full' };
  return { tier: 'blocked' };
}

export function useOrgAccess(): OrgAccessData {
  // The installation endpoints only work for GitHub-App tokens; a classic PAT
  // 403s on /user/installations (and the install model doesn't apply to it at
  // all). Don't even fire the queries for PAT — the section explains instead.
  const method = getCredential()?.method ?? 'github-app';
  const enabled = method === 'github-app';

  // queryFn returns the raw GitHub payload; `select` (a stable module-level
  // mapper) normalizes it — cache stays canonical, transform is memoized.
  const installs = useQuery({
    queryKey: ['installations'],
    queryFn: fetchUserInstallations,
    select: toAppInstallations,
    placeholderData: (prev) => prev,
    staleTime: 60_000,
    enabled,
  });
  const memberships = useQuery({
    queryKey: ['org-memberships'],
    queryFn: fetchOrgMemberships,
    select: toOrgMemberships,
    placeholderData: (prev) => prev,
    staleTime: 5 * 60_000,
    enabled,
  });
  const entitlement = useEntitlement();
  const entLoading = useEntitlementLoading();

  // Cross-query derivation (installs × memberships × entitlement) can't live in
  // a per-query `select` — memoize it here so it only recomputes on real change.
  const installed = useMemo<InstalledAccount[]>(() => {
    const roleByOrgId = new Map(
      (memberships.data ?? []).map((m) => [m.id, m.role]),
    );
    return (installs.data ?? []).map((i) => ({
      ...i,
      role:
        i.account.type === 'User'
          ? 'owner'
          : (roleByOrgId.get(i.account.id) ?? 'member'),
      plan: planForAccount(i, entitlement, entLoading),
    }));
  }, [installs.data, memberships.data, entitlement, entLoading]);

  const isLoading = enabled && (installs.isPending || memberships.isPending);
  return {
    method,
    isLoading,
    isRefreshing:
      enabled && !isLoading && (installs.isFetching || memberships.isFetching),
    isError: enabled && (installs.isError || memberships.isError),
    installed,
    refetch: () => {
      void installs.refetch();
      void memberships.refetch();
    },
  };
}
