// Role-aware CTA cluster for a gated org (ADR 0020). Shared by the Settings org
// card (`size="card"`) and the full-screen blocked explainer (`size="screen"`).
//
//   reason 'no-plan'    → org has no plan.   admin: Start free trial · Buy seats
//   reason 'seats-full' → org is paid, full. admin: Add seats (no trial — it
//                         already has a plan; the ask is a seat, not a trial)
//   member (either)     → an informational banner. There's no in-app way to
//                         notify an admin, so it's not a (dead) button.
//
// Start trial / Buy seats / Add seats open the per-org Polar checkout/portal.

import { Clock, Info, Loader2, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { OrgRole } from '../auth/oauthBroker';
import { canManageBilling, useBillingAction } from './entitlement';

export type GateReason = 'no-plan' | 'seats-full';

export function OrgPlanActions({
  githubOrgId,
  login,
  role,
  reason = 'no-plan',
  size = 'card',
}: {
  githubOrgId: number;
  login: string;
  role: OrgRole;
  reason?: GateReason;
  size?: 'card' | 'screen';
}) {
  const big = size === 'screen';
  const btnSize = big ? 'default' : 'sm';
  const { pending, manageSeats, checkout } = useBillingAction();

  if (canManageBilling(role)) {
    return (
      <div className={big ? 'flex flex-col items-center gap-3' : 'space-y-2'}>
        <div className={`flex flex-wrap items-center gap-2 ${big ? 'justify-center' : ''}`}>
          {reason === 'seats-full' ? (
            // Paid org, no free seat for the viewer → manage the existing
            // subscription (Polar portal) to add one.
            <Button
              size={btnSize}
              disabled={pending}
              onClick={() => manageSeats(githubOrgId)}
            >
              {pending ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <UserPlus className="size-4" />
              )}{' '}
              Add seats
            </Button>
          ) : (
            // No plan yet → Polar checkout. The product's 14-day trial (card
            // required) converts automatically, so this single CTA is both the
            // "try" and the "buy" — there's no separate no-trial purchase, and
            // the customer portal has nothing to manage until checkout runs.
            <Button
              size={btnSize}
              disabled={pending}
              onClick={() => checkout(githubOrgId)}
            >
              {pending ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <Clock className="size-4" />
              )}{' '}
              Start free trial
            </Button>
          )}
        </div>
        {reason === 'no-plan' && (
          <p className="text-[11.5px] text-muted-foreground/70">
            14-day trial · card required · converts automatically
          </p>
        )}
      </div>
    );
  }

  // Members have no self-serve path and there's no in-app way to notify an
  // admin — so this is a plain informational banner, not a (dead) button.
  return (
    <div
      className={`flex items-start gap-2.5 rounded-lg border border-border bg-background px-3.5 py-3 text-left ${big ? 'mx-auto max-w-[400px]' : ''}`}
    >
      <Info className="mt-px size-4 shrink-0 text-muted-foreground" />
      <p className="text-[12.5px] leading-relaxed text-muted-foreground">
        {reason === 'seats-full' ? (
          <>
            <span className="font-medium text-foreground">{login}</span>'s seats are
            all in use. Ask an owner or admin to add a seat for you — only they can
            change billing.
          </>
        ) : (
          <>
            Ask an owner or admin of{' '}
            <span className="font-medium text-foreground">{login}</span> to set up
            Pyor — they can start a free trial that adds a seat for you. Only owners
            and admins can do this.
          </>
        )}
      </p>
    </div>
  );
}
